const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaultCategories=[{id:'inbox',name:'Inbox',icon:'Inbox',color:'#b9c990'},{id:'todo',name:'To do',icon:'ListTodo',color:'#a9c7e3'},{id:'ideas',name:'Ideas',icon:'Lightbulb',color:'#e2cf83'},{id:'read',name:'Read later',icon:'BookOpen',color:'#c3b5dc'},{id:'places',name:'Places',icon:'MapPin',color:'#e7a170'},{id:'inspiration',name:'Inspiration',icon:'Palette',color:'#a2c8b1'}];
const CATEGORY_KEY='pasteinn-preview-categories-v1';const library=window.lucide;let categories=defaultCategories.map(x=>({...x})),categoryStorage=true;
const validDrawing=d=>typeof d==='string'&&[64,256,1024].includes(d.length)&&/^[01]+$/.test(d)&&d.includes('1');
let archivedCategories=[];
function allCrates(){return [...categories,...archivedCategories]}
function persistCrates(){localStorage.setItem(CATEGORY_KEY,JSON.stringify(allCrates()));categoryStorage=true}
const validColor=c=>typeof c==='string'&&/^#[0-9a-f]{6}$/i.test(c);const validIcon=n=>typeof n==='string'&&!!library?.icons?.[n];
try{const stored=JSON.parse(localStorage.getItem(CATEGORY_KEY)||'null');if(Array.isArray(stored)&&stored.length){const valid=stored.filter(c=>c&&typeof c.id==='string'&&/^[a-z0-9-]+$/i.test(c.id)&&typeof c.name==='string'&&c.name.trim()&&c.name.length<=28&&validColor(c.color)&&(validIcon(c.icon)||(c.icon==='HandDrawn'&&validDrawing(c.drawing))));const ids=new Set(),unique=valid.filter(c=>!ids.has(c.id)&&ids.add(c.id));categories=unique.filter(c=>!c.deleted);archivedCategories=unique.filter(c=>c.deleted);if(!categories.some(c=>c.id==='inbox'))categories.unshift({...defaultCategories[0]});}}catch{categoryStorage=false}
function iconHTML(name,color,size=20,drawing){if(name==='HandDrawn'){const bitmap=validDrawing(drawing)?drawing:'0'.repeat(256);const grid=Math.sqrt(bitmap.length);return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${grid} ${grid}" width="${size}" height="${size}" aria-hidden="true" fill="currentColor" stroke="none" style="color:${validColor(color)?color:'inherit'};shape-rendering:crispEdges">${[...bitmap].map((v,i)=>v==='1'?`<rect x="${i%grid}" y="${Math.floor(i/grid)}" width="1" height="1"/>`:'').join('')}</svg>`;}if(!library?.createElement)return '<span aria-hidden="true">□</span>';return library.createElement(library.icons[name]||library.icons.Folder,{width:size,height:size,'stroke-width':1.7,'aria-hidden':'true',style:validColor(color)?'color:'+color:''}).outerHTML}
function hydrateIcons(root=document){if(library?.createIcons)library.createIcons({icons:library.icons,root,attrs:{'stroke-width':1.7,'aria-hidden':'true'}})}
let selected=0,onlyCategory=false,notes=[],toastTimer;
function data(){const view=$('view-filter')?.value||'all';return [...notes.filter(n=>!n.redacted&&(view==='trash'?n.deleted:!n.deleted&&(view!=='pinned'||n.pinned)))]}function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4000)}
function render(){
  const q=$('search').value.trim().toLowerCase();
  const days=Number($('date-filter')?.value||0);const items=data().filter(x=>(!days||x.createdAt>=Date.now()-days*86400000)&&(!onlyCategory||x.category===categories[selected].id)&&`${x.title} ${x.body} ${x.ocrText||''} ${(x.tags||[]).join(' ')} ${x.metadata?.title||''} ${x.metadata?.description||''} ${(x.images||[]).map(i=>i.name).join(' ')}`.toLowerCase().includes(q));
  $('category-filter').textContent=onlyCategory?categories[selected].name:'All chests';$('category-filter').setAttribute('aria-pressed',String(onlyCategory));
  $('items').innerHTML=items.length?items.map(x=>{
    const category=categories.find(c=>c.id===x.category)||categories[0];
    const media=x.images?.length?`<div class="card-images">${imageMarkup(x.images[0])}${x.images.length>1?`<span class="image-count">+${x.images.length-1}</span>`:''}</div>`:'';
    const content=x.url?previewMarkup({url:x.url,metadata:x.metadata},'link-preview saved-link'):`<h3>${esc(x.title)}</h3>`;
    const body=x.url?x.body.replace(/https?:\/\/[^\s<>]+/,'').trim():x.body===x.title?'':x.body;
    return `<button class="item" type="button" data-open="${x.id}">${media}<span class="item-type">${x.pinned?'★ · ':''}${esc((x.type||'note').toUpperCase())}${x.conflict?' · CONFLICT COPY':''}</span>${content}${body?`<p>${esc(body)}</p>`:''}<span class="item-meta"><span class="card-category">${iconHTML(category.icon,category.color,14,category.drawing)}${esc(category.name)}</span><span>${x.localOnly?'Device only':esc(x.time)}</span></span></button>`;
  }).join(''):`<div class="empty">${q?'Nothing by that name.':onlyCategory?'This chest is still empty.':'Your next good find goes here.'}</div>`;
}
const wheel=$('category-wheel');let wheelButtons=[];function renderWheel(){wheel.innerHTML='<div class="wheel-padding" aria-hidden="true"></div>'+categories.map(c=>`<button class="wheel-item" type="button" data-category="${esc(c.id)}" aria-label="Save to ${esc(c.name)}" aria-pressed="false">${iconHTML(c.icon,c.color,20,c.drawing)}<span class="category-name">${esc(c.name)}</span></button>`).join('')+'<div class="wheel-padding" aria-hidden="true"></div>';wheelButtons=[...wheel.querySelectorAll('.wheel-item')];}const reduced=matchMedia('(prefers-reduced-motion: reduce)');
function setSelected(i){selected=Math.max(0,Math.min(categories.length-1,i));wheelButtons.forEach((b,n)=>{b.classList.toggle('selected',n===selected);b.setAttribute('aria-pressed',String(n===selected))});$('previous-category').disabled=selected===0;$('next-category').disabled=selected===categories.length-1;$('category-status').textContent='Saving to '+categories[selected].name;render()}
function selectCategory(i,smooth=true){i=Math.max(0,Math.min(categories.length-1,i));setSelected(i);wheel.scrollTo({top:i*50,behavior:smooth&&!reduced.matches?'smooth':'instant'})}
function paintWheel(){const center=wheel.scrollTop/50;wheelButtons.forEach((b,n)=>{const d=Math.max(-2,Math.min(2,n-center));b.style.transform=`perspective(350px) rotateX(${d*-24}deg) scale(${1-Math.abs(d)*.075})`;b.style.opacity=String(Math.max(.12,1-Math.abs(d)*.66))})}let settleTimer,drag=null,suppressClick=false;
wheel.addEventListener('scroll',()=>{if(document.getElementById('appearance-dialog')?.open)return;paintWheel();const n=Math.round(wheel.scrollTop/50);if(n!==selected)setSelected(n);clearTimeout(settleTimer);if(!drag)settleTimer=setTimeout(()=>{const nearest=Math.round(wheel.scrollTop/50);if(Math.abs(wheel.scrollTop-nearest*50)>1)selectCategory(nearest)},150)},{passive:true});
wheel.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'||e.button!==0)return;drag={id:e.pointerId,startY:e.clientY,startScroll:wheel.scrollTop,lastY:e.clientY,lastTime:performance.now(),velocity:0,moved:false};wheel.classList.add('dragging');});
wheel.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const delta=e.clientY-drag.startY;if(Math.abs(delta)>4&&!drag.moved){drag.moved=true;wheel.setPointerCapture(e.pointerId)}if(!drag.moved)return;e.preventDefault();const now=performance.now(),dt=now-drag.lastTime;drag.velocity=dt>0?(drag.lastY-e.clientY)/dt:0;drag.lastY=e.clientY;drag.lastTime=now;wheel.scrollTop=drag.startScroll-delta});
function endDrag(e){if(!drag||drag.id!==e.pointerId)return;const d=drag;drag=null;wheel.classList.remove('dragging');if(wheel.hasPointerCapture(e.pointerId))wheel.releasePointerCapture(e.pointerId);if(d.moved){suppressClick=true;const recent=performance.now()-d.lastTime<100;selectCategory(Math.round((wheel.scrollTop+(recent?Math.max(-150,Math.min(150,d.velocity*130)):0))/50));setTimeout(()=>suppressClick=false,0)}}
wheel.addEventListener('pointerup',endDrag);wheel.addEventListener('pointercancel',endDrag);wheel.addEventListener('pointerleave',e=>{if(drag&&!drag.moved)endDrag(e)});
wheel.addEventListener('click',e=>{if(suppressClick)return;const b=e.target.closest('[data-category]');if(b)selectCategory(categories.findIndex(c=>c.id===b.dataset.category))});
wheel.addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?categories.length-1:selected+(e.key==='ArrowDown'?1:-1);selectCategory(n);wheelButtons[selected].focus({preventScroll:true})}});
$('previous-category').onclick=()=>selectCategory(selected-1);$('next-category').onclick=()=>selectCategory(selected+1);
$('search').oninput=render;$('category-filter').onclick=()=>{onlyCategory=!onlyCategory;render()};$('appearance').onclick=()=>{$('appearance').textContent=document.body.classList.toggle('light')?'Morning light':'After hours'};
function detail(title,body,type,url,record){$('detail-media').innerHTML=record?(record.images||[]).map(x=>`<a href="${imageURL(x)}" download="${esc(x.name)}">${imageMarkup(x,'detail-image')}</a>${x.compressed?'<p class="small-note">Synced image copy · original on the capture device.</p>':''}`).join('')+(record.url?previewMarkup({url:record.url,metadata:record.metadata}):''):'';$('delete-save').hidden=!record?.createdAt;$('delete-save').dataset.id=record?.id||'';$('detail-title').textContent=title;$('detail-body').textContent=body;$('detail-type').textContent=type;$('detail-link').hidden=!url;if(url)$('detail-link').href=url;else $('detail-link').removeAttribute('href');refreshDetail(record);$('detail').showModal()}
$('about-preview').onclick=()=>detail('A little work in progress.','Paste images, links, and notes. Saves stay in this browser on this device; clearing browser data removes them. Link previews contact the original website, and thumbnails load from that site. Local saves and downloaded backups are unencrypted. Image OCR runs here in English; photos, audio/video attachments, voice recording, editing, trash and backup/restore are available. Optional GitHub sync encrypts content before upload. Keep a backup and your recovery key safe.','DESIGN PREVIEW');document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.open){const x=data().find(x=>x.id===b.dataset.open);detail(x.title,x.body,(categories.find(c=>c.id===x.category)||categories[0]).name,x.url,x)}if(b.dataset.planned)detail(b.dataset.planned,'Part of the product brief. For now, paste an image, a link, or a note.','PLANNED')});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('search').focus()}if((e.metaKey||e.ctrlKey)&&e.key==='Enter'&&document.activeElement===$('capture'))$('capture-form').requestSubmit()});
