const iconNames=(()=>{const seen=new Set();return Object.keys(library?.icons||{}).filter(n=>{const key=JSON.stringify(library.icons[n]);if(seen.has(key))return false;seen.add(key);return true})})();
const popularIcons=['Inbox','ListTodo','Lightbulb','BookOpen','MapPin','Palette','Folder','Archive','Box','Briefcase','Heart','Star','Bookmark','Coffee','Leaf','Flower','Sun','Moon','Cloud','Flame','Mountain','TreePine','House','Plane','Car','Bike','TrainFront','Utensils','CookingPot','ShoppingBag','Gift','Camera','Image','Music','Headphones','Film','Gamepad2','Laptop','Code','Terminal','Globe','Link','FileText','Notebook','Pencil','PenTool','Brush','Scissors','Wrench','Settings','Calendar','Clock','AlarmClock','Timer','Check','CircleCheck','ListChecks','Target','Flag','Trophy','GraduationCap','School','Library','Brain','Sparkles','Zap','KeyRound','Lock','Shield','PiggyBank','Wallet','Gem','Diamond','Rocket','Tent','Compass','Binoculars','Fish','Cat','Dog','Rabbit','Bird','Smile','MessageCircle','Mail','Send','Users','User','Sprout'].filter(validIcon);
const swatches=['#b9c990','#e2cf83','#e7a170','#dfaaa4','#c3b5dc','#a9c7e3','#a2c8b1','#eeeeda'];let draft=null,iconLimit=60;
function draftPreview(){$('category-live-icon').innerHTML=iconHTML(draft.icon,draft.color,30,draft.drawing);$('category-live-icon').style.color=draft.color;if(typeof renderDrawing==='function')renderDrawing()}
function renderColors(){$('color-options').innerHTML=swatches.map(c=>`<button type="button" class="color-swatch" data-color="${c}" style="--swatch:${c}" aria-label="Use color ${c}" aria-pressed="${draft.color.toLowerCase()===c}"></button>`).join('')+`<label class="custom-color">Custom<input type="color" id="category-color" value="${draft.color}" aria-label="Custom icon color"></label>`}
function iconLabel(n){return n.replace(/([a-z0-9])([A-Z])/g,'$1 $2')}
function renderIconPicker(){const q=$('icon-search').value.trim().toLowerCase().replace(/[^a-z0-9]/g,'');const names=q?iconNames.filter(n=>n.toLowerCase().includes(q)):[...popularIcons,...iconNames.filter(n=>!popularIcons.includes(n))];const shown=names.slice(0,iconLimit);$('icon-picker').innerHTML=shown.length?shown.map(n=>`<button type="button" class="icon-option" data-icon-choice="${n}" aria-label="${esc(iconLabel(n))}" aria-pressed="${draft.icon===n}">${iconHTML(n,draft.color,22)}</button>`).join(''):'<p class="no-icons">No matching icons.</p>';$('more-icons').hidden=names.length<=iconLimit;$('more-icons').textContent=`More icons (${Math.min(iconLimit,names.length)} of ${names.length})`}
function populateDraft(id){const c=categories.find(c=>c.id===id);draft=c?{...c}:{id:null,name:'',icon:'Folder',color:'#b9c990'};$('category-name').value=draft.name;$('icon-search').value='';$('category-error').textContent='';$('category-edit-select').value=id||'new';iconLimit=60;renderColors();draftPreview();renderIconPicker();resetDrawingEditor()}
function openEditor(){if(!library){toast('The icon library could not load. Please reload.');return}$('category-edit-select').innerHTML=categories.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')+'<option value="new">New category…</option>';populateDraft(categories[selected].id);$('category-local-status').textContent=categoryStorage?'Saved in this browser':'Session only · storage unavailable';$('category-editor').showModal()}
$('edit-categories').onclick=openEditor;$('category-edit-select').onchange=e=>populateDraft(e.target.value);$('new-category').onclick=()=>{populateDraft('new');$('category-name').focus()};$('icon-search').oninput=()=>{iconLimit=60;renderIconPicker()};$('more-icons').onclick=()=>{iconLimit+=60;renderIconPicker()};
$('color-options').addEventListener('click',e=>{const b=e.target.closest('[data-color]');if(!b)return;draft.color=b.dataset.color;renderColors();draftPreview();renderIconPicker()});$('color-options').addEventListener('input',e=>{if(e.target.id==='category-color'){draft.color=e.target.value;draftPreview();document.querySelectorAll('[data-color]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.color===draft.color)));$('icon-picker').style.color=draft.color;renderIconPicker()}});
