$('category-form').onsubmit=e=>{e.preventDefault();const name=$('category-name').value.trim().replace(/\s+/g,' ');if(!name||name.length>28){$('category-error').textContent='Use a name between 1 and 28 characters.';return}if(categories.some(c=>c.id!==draft.id&&c.name.toLocaleLowerCase()===name.toLocaleLowerCase())){$('category-error').textContent='That crate name is already in use.';return}if(!validColor(draft.color)||!(validIcon(draft.icon)||(draft.icon==='HandDrawn'&&validDrawing(draft.drawing)))){$('category-error').textContent='Choose an icon or draw a few pixels, and pick a color.';return}const saved=PasteInnProtocol.revised({...categories.find(c=>c.id===draft.id),id:draft.id||'custom-'+crypto.randomUUID(),name,icon:draft.icon,color:draft.color,...(draft.icon==='HandDrawn'?{drawing:draft.drawing}:{})});let index=categories.findIndex(c=>c.id===saved.id);if(index<0){categories.push(saved);index=categories.length-1}else categories[index]=saved;try{persistCrates()}catch{categoryStorage=false}clearTimeout(settleTimer);renderWheel();selectCategory(index,false);paintWheel();$('category-editor').close();notifyLocalChange();toast(categoryStorage?'Crate saved':'Crate changed for this session. Browser storage is unavailable.')};
